void radix(std::vector<std::complex<double>>& values,bool inverse,Work& work){const auto n=values.size();for(std::size_t i=1,j=0;i<n;++i){std::size_t bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)std::swap(values[i],values[j]);}for(std::size_t length=2;length<=n;length<<=1){work.spend(n);const double angle=(inverse?2:-2)*std::acos(-1.0)/length;const std::complex<double> root(std::cos(angle),std::sin(angle));for(std::size_t begin=0;begin<n;begin+=length){std::complex<double> factor=1;for(std::size_t j=0;j<length/2;++j){const auto u=values[begin+j],v=values[begin+j+length/2]*factor;values[begin+j]=u+v;values[begin+j+length/2]=u-v;factor*=root;}}}if(inverse)for(auto& value:values)value/=n;}
